const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

type Application = {
  id: string;
  salutation: string | null;
  first_name: string;
  last_name: string;
  email: string;
  phone: string | null;
  birthdate: string | null;
  street: string | null;
  zip: string | null;
  city: string | null;
  membership_type: string;
  contribution_interval: string;
  statutes_accepted: boolean;
  data_processing_accepted: boolean;
  /** Antworten auf die frei zusammengestellten Zusatzfragen. */
  extra: Record<string, { label: string; wert: unknown }> | null;
  created_at: string;
};

const fmtDate = (d: string | null) => {
  if (!d) return "";
  try {
    const x = new Date(d);
    return `${String(x.getDate()).padStart(2, "0")}.${String(x.getMonth() + 1).padStart(2, "0")}.${x.getFullYear()}`;
  } catch {
    return d ?? "";
  }
};

// Helvetica nutzt WinAnsi und kann ä ö ü ß abbilden – nur normalisieren.
const safe = (s: string | null | undefined) => (s ?? "").normalize("NFC");

async function getCurrentRate(client: ReturnType<typeof createClient>): Promise<number> {
  try {
    const { data } = await client.rpc("get_current_contribution_rate");
    const n = typeof data === "number" ? data : Number(data);
    if (Number.isFinite(n) && n > 0) return n;
  } catch (_) {/* ignore */}
  return 36;
}

// Aemter, die im Aufnahmeantrag ausgewiesen werden – Auswahl, Beschriftung und
// Reihenfolge kommen aus role_catalog, nicht mehr aus einer Liste im Code.
export interface Official { label: string; name: string }

async function getOfficials(client: ReturnType<typeof createClient>): Promise<Official[]> {
  const { data, error } = await client.rpc("get_board_members");

  if (!error && Array.isArray(data)) {
    return (data as { role_label: string; display_name: string | null }[])
      .map((r) => ({ label: r.role_label, name: r.display_name ?? "" }));
  }

  // Rueckfallweg, solange die Migration 20260907190000 nicht eingespielt ist.
  // Entspricht dem bisherigen Verhalten und kann danach entfallen.
  const fallback: Official[] = [
    { label: "1. Officiatus", name: "" },
    { label: "2. Officiatus", name: "" },
    { label: "Schatzmeister", name: "" },
  ];
  const keys = ["officiatus_1", "officiatus_2", "schatzmeister"];
  const { data: roles } = await client
    .from("user_roles").select("user_id, role").in("role", keys);
  if (!roles?.length) return fallback;

  const ids = [...new Set(roles.map((r: { user_id: string }) => r.user_id))];
  const { data: profs } = await client
    .from("profiles").select("id, display_name, first_name, last_name").in("id", ids);

  for (const r of roles as { user_id: string; role: string }[]) {
    const i = keys.indexOf(r.role);
    if (i < 0 || fallback[i].name) continue;
    const pr = (profs ?? []).find((x: { id: string }) => x.id === r.user_id) as
      | { display_name?: string; first_name?: string; last_name?: string } | undefined;
    if (!pr) continue;
    fallback[i].name =
      (pr.display_name || [pr.first_name, pr.last_name].filter(Boolean).join(" ")).trim();
  }
  return fallback;
}

// ── Logo (JPEG, als Base64 eingebettet) ──────────────────────────────────────
const LOGO_B64 = "";

function b64ToUint8(b64: string): Uint8Array {
  const bin = atob(b64);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return arr;
}

/**
 * Das hinterlegte Logo, falls pdf-lib es lesen kann.
 *
 * PNG und JPEG – mehr kann pdf-lib nicht einbetten. Ein WebP oder SVG ergibt
 * hier `null`, und der Antrag wird ohne Logo gedruckt statt mit einer
 * Fehlermeldung abzubrechen: Eine fehlende Grafik darf keine Aufnahme
 * verhindern.
 */
async function ladeLogo(pdf: PDFDocument, pfad: string) {
  if (!pfad) return null;
  try {
    const basis = Deno.env.get("SUPABASE_URL");
    if (!basis) return null;
    const antwort = await fetch(
      `${basis}/storage/v1/object/public/gallery/${pfad.split("/").map(encodeURIComponent).join("/")}`
    );
    if (!antwort.ok) return null;
    const bytes = new Uint8Array(await antwort.arrayBuffer());

    // Nach den ersten Bytes gehen, nicht nach der Dateiendung: Die sagt nur,
    // wie die Datei heisst.
    const istPng = bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47;
    const istJpeg = bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff;
    if (istPng) return await pdf.embedPng(bytes);
    if (istJpeg) return await pdf.embedJpg(bytes);
    return null;
  } catch (err) {
    console.error("Logo fuer den Antrag nicht ladbar:", err);
    return null;
  }
}

/** Hex aus den Vereinsangaben in die Farbdarstellung von pdf-lib. */
function hexFarbe(hex: string, ersatz: [number, number, number]) {
  const m = /^#?([0-9a-f]{6})$/i.exec((hex ?? "").trim());
  if (!m) return rgb(...ersatz);
  const z = parseInt(m[1], 16);
  return rgb(((z >> 16) & 255) / 255, ((z >> 8) & 255) / 255, (z & 255) / 255);
}

interface AntragsTexte {
  titel: string;
  erklaerung: { titel: string; zeilen: string[] };
  datenschutz: { titel: string; text: string };
  zustimmungen: string[];
  fussnote: string[];
}

/**
 * Die Textbausteine des Antrags aus der Verwaltung.
 *
 * Beitragssatz und Vereinsname werden hier eingesetzt, damit in der Vorlage
 * `{{beitrag}}` und `{{verein}}` stehen kann statt einer Zahl, die jemand
 * jaehrlich von Hand nachziehen muesste.
 */
async function antragsTexte(betrag: number, modell: Beitragsmodell): Promise<AntragsTexte> {
  const werte = { beitrag: betrag.toFixed(2).replace(".", ",") };
  // Der Satz zum Beitrag haengt am Modell: „Derzeit betraegt der jaehrliche
  // Beitragssatz …" waere falsch, wenn es gar keinen gibt.
  const beitragsSchluessel = modell === "umlage" ? "beitrag_umlage"
    : modell === "keiner" ? "beitrag_keiner"
    : "beitrag_fest";

  const [titel, erklaerung, beitragsSatz, datenschutz, zustimmungen, fussnote] = await Promise.all([
    pdfText("titel", werte),
    pdfText("erklaerung", werte),
    pdfText(beitragsSchluessel, werte),
    pdfText("datenschutz", werte),
    pdfText("zustimmungen", werte),
    pdfText("fussnote", werte),
  ]);
  const zeilen = (t: string) => t.split("
").map((z) => z.trim()).filter(Boolean);
  return {
    titel: titel.inhalt,
    erklaerung: {
      titel: erklaerung.titel,
      zeilen: [...zeilen(erklaerung.inhalt), ...zeilen(beitragsSatz.inhalt)],
    },
    datenschutz: { titel: datenschutz.titel, text: datenschutz.inhalt },
    zustimmungen: zeilen(zustimmungen.inhalt),
    fussnote: zeilen(fussnote.inhalt),
  };
}

type Beitragsmodell = "fest" | "umlage" | "keiner";

interface Beitragsangaben {
  modell: Beitragsmodell;
  arten: { key: string; label: string; amount: number | null }[];
}

/** Modell und Mitgliedsarten – dieselbe Abfrage, die auch das Formular nutzt. */
async function beitragsangaben(client: ReturnType<typeof createClient>): Promise<Beitragsangaben> {
  const { data } = await client.rpc("public_contribution_settings");
  const zeile = (data as { model: string; options: unknown }[] | null)?.[0];
  const arten = Array.isArray(zeile?.options)
    ? (zeile!.options as { key: string; label: string; amount: unknown }[]).map((a) => ({
        key: a.key,
        label: a.label,
        amount: a.amount === null || a.amount === undefined ? null : Number(a.amount),
      }))
    : [];
  const modell = (["fest", "umlage", "keiner"] as const).includes(zeile?.model as Beitragsmodell)
    ? (zeile!.model as Beitragsmodell)
    : "fest";
  // Ohne gepflegte Kategorien bleibt es bei dem, was frueher fest im Code stand.
  return {
    modell,
    arten: arten.length > 0
      ? arten
      : [{ key: "aktiv", label: "Aktives Mitglied", amount: null },
         { key: "foerder", label: "Fördermitglied", amount: null }],
  };
}

async function buildApplicationPdf(
  app: Application,
  rate: number,
  officials: Official[],
  m: Marke,
  texte: AntragsTexte,
  beitrag: Beitragsangaben
): Promise<Uint8Array> {
  const pdf = await PDFDocument.create();
  const page = pdf.addPage([595.28, 841.89]); // A4
  const font   = await pdf.embedFont(StandardFonts.Helvetica);
  const bold   = await pdf.embedFont(StandardFonts.HelveticaBold);
  const italic = await pdf.embedFont(StandardFonts.HelveticaOblique);

  // Zuerst das Logo aus den Vereinsangaben. Nur wenn dort keins liegt, greift
  // das mitgelieferte – und auch das nur, solange die Installation den Namen
  // traegt, zu dem es gehoert: lieber kein Logo als ein fremdes auf einem
  // Aufnahmeantrag.
  const eigenes = await ladeLogo(pdf, m.logoPfad);
  const logoImg = eigenes
    ?? (m.name === "Diu lebendec Histôrje e. V." ? await pdf.embedPng(b64ToUint8(LOGO_B64)) : null);
  // Das mitgelieferte Logo ist auf 0.14 abgestimmt; ein hochgeladenes kommt in
  // beliebiger Groesse und wird auf eine feste Hoehe gebracht.
  const logoDims = !logoImg ? null
    : eigenes ? logoImg.scale(46 / logoImg.height)
    : logoImg.scale(0.14);

  // ── Farben ────────────────────────────────────────────────────────────────
  const AMBER = hexFarbe(m.farbe, [0.851, 0.467, 0.024]);
  const DARK  = hexFarbe(m.dunkel, [0.11, 0.11, 0.13]);
  const GRAY  = rgb(0.45,  0.45,  0.48);
  const LGRAY = rgb(0.93,  0.93,  0.94);
  const WHITE = rgb(1,     1,     1);

  const L = 44;
  const R = 551;
  const W = R - L;

  const safe = (s: string | null | undefined) => (s ?? "").normalize("NFC");

  // ── Hilfsfunktionen ───────────────────────────────────────────────────────

  const at = (s: string, x: number, yy: number, sz = 10, f = font, col = DARK) => {
    page.drawText(safe(s), { x, y: yy, size: sz, font: f, color: col });
  };

  const textBlock = (
    s: string, x: number, startY: number, sz: number,
    f = font, col = DARK, maxW = W - (x - L)
  ): number => {
    const words = safe(s).split(/\s+/);
    let line = "";
    let cy = startY;
    for (const w of words) {
      const t = line ? line + " " + w : w;
      if (f.widthOfTextAtSize(t, sz) > maxW) {
        if (line) { page.drawText(line, { x, y: cy, size: sz, font: f, color: col }); cy -= sz + 3; }
        line = w;
      } else line = t;
    }
    if (line) { page.drawText(line, { x, y: cy, size: sz, font: f, color: col }); cy -= sz + 3; }
    return cy;
  };

  const field = (label: string, value: string, x: number, yy: number, valueX = x + 148) => {
    page.drawText(safe(label), { x, y: yy, size: 9, font: bold, color: GRAY });
    page.drawText(safe(value), { x: valueX, y: yy, size: 10, font, color: DARK });
  };

  const checkbox = (x: number, yy: number, checked: boolean) => {
    page.drawRectangle({ x, y: yy - 1, width: 9, height: 9,
      borderColor: AMBER, borderWidth: checked ? 0 : 0.8,
      color: checked ? AMBER : WHITE });
    if (checked) at("x", x + 1.5, yy + 0.5, 8, bold, WHITE);
  };

  const hline = (yy: number, col = LGRAY, thick = 0.6) =>
    page.drawLine({ start: { x: L, y: yy }, end: { x: R, y: yy }, thickness: thick, color: col });

  // ── HEADER ────────────────────────────────────────────────────────────────
  page.drawRectangle({ x: 0, y: 807, width: 595.28, height: 5, color: AMBER });
  page.drawRectangle({ x: 0, y: 735, width: 595.28, height: 72, color: rgb(0.13, 0.13, 0.15) });
  if (logoImg && logoDims) {
    page.drawImage(logoImg, { x: R - logoDims.width, y: 740, width: logoDims.width, height: logoDims.height });
  }
  at(m.name, L, 781, 20, bold, WHITE);
  if (m.tagline) at(m.tagline, L, 760, 8.5, font, rgb(0.75, 0.75, 0.78));
  const anschriftZeile = [m.strasse, m.ort].filter(Boolean).join(" - ");
  if (anschriftZeile) at(anschriftZeile, L, 742, 8, italic, rgb(0.65, 0.65, 0.68));

  // ── VORSTANDSLEISTE ───────────────────────────────────────────────────────
  page.drawRectangle({ x: L, y: 705, width: W, height: 22, color: rgb(0.97, 0.97, 0.97) });
  // Spaltenbreite richtet sich nach der Zahl der Aemter – ein Verein mit zwei
  // oder vier ausgewiesenen Posten bekommt entsprechend zwei oder vier Spalten.
  const colW = W / Math.max(officials.length, 1);
  for (let i = 0; i < officials.length; i++) {
    const { label: title, name } = officials[i];
    const ox = L + i * colW + 8;
    at(title + ":", ox, 718, 7.5, bold, GRAY);
    at(name, ox + bold.widthOfTextAtSize(title + ": ", 7.5), 718, 7.5, font, DARK);
  }
  page.drawRectangle({ x: L, y: 703, width: W, height: 1.5, color: AMBER });

  // ── TITEL ─────────────────────────────────────────────────────────────────
  let y = 681;
  page.drawRectangle({ x: L, y: y - 2, width: 3.5, height: 16, color: AMBER });
  at(texte.titel, L + 10, y, 14, bold, DARK);
  y -= 28;

  // ── PERSÖNLICHE ANGABEN ───────────────────────────────────────────────────
  at("PERSÖNLICHE ANGABEN", L, y, 7.5, bold, AMBER);
  y -= 4; hline(y); y -= 14;

  field("Anrede", safe(app.salutation ?? ""), L, y);
  field("Geburtsdatum", fmtDate(app.birthdate), L + W / 2, y, L + W / 2 + 90);
  y -= 16;
  field("Name, Vorname", safe(app.last_name) + ", " + safe(app.first_name), L, y);
  y -= 16;
  field("Straße und Hausnr.", safe(app.street ?? ""), L, y);
  y -= 16;
  field("PLZ und Wohnort", (safe(app.zip ?? "") + " " + safe(app.city ?? "")).trim(), L, y);
  y -= 16;
  field("E-Mail", safe(app.email), L, y);
  y -= 16;
  field("Telefon / Handy", safe(app.phone ?? ""), L, y);
  y -= 24;

  // ── MITGLIEDSCHAFT ────────────────────────────────────────────────────────
  at("MITGLIEDSCHAFT & BEITRAG", L, y, 7.5, bold, AMBER);
  y -= 4; hline(y); y -= 14;

  // Die Mitgliedsarten kommen aus der Verwaltung, nicht aus einer Liste im
  // Code. Sie brauchen mehr Platz als die frueheren zwei, sobald ein Verein
  // „Student" und „Rentner" ergaenzt – deshalb Umbruch statt einer Zeile.
  at("Art der Mitgliedschaft:", L, y, 9, bold, GRAY);
  let cx = L + 148;
  for (const art of beitrag.arten) {
    const beschriftung = beitrag.modell === "fest" && art.amount !== null
      ? `${art.label} (${art.amount.toFixed(2).replace(".", ",")} €)`
      : art.label;
    const breite = 14 + font.widthOfTextAtSize(beschriftung, 10) + 20;
    if (cx + breite > R) { cx = L + 148; y -= 15; }
    checkbox(cx, y, app.membership_type === art.key);
    at(beschriftung, cx + 14, y, 10, font, DARK);
    cx += breite;
  }
  y -= 18;

  const rateStr  = rate.toFixed(2).replace(".", ",");
  const halfRate = (rate / 2).toFixed(2).replace(".", ",");

  // Ein Zahlungsrhythmus ergibt nur beim festen Beitrag Sinn: Bei einer Umlage
  // gibt es eine Abrechnung im Jahr, ohne Beitrag gar keine.
  if (beitrag.modell === "fest") {
    at("Beitragseinzug:", L, y, 9, bold, GRAY);
    cx = L + 148;
    for (const [val, label, sub] of [
      ["jaehrlich",     "Jährlich",    rateStr + " € / Jahr"],
      ["halbjaehrlich", "Halbjährlich", halfRate + " € / Halbjahr"],
    ] as const) {
      checkbox(cx, y, app.contribution_interval === val);
      at(label, cx + 14, y, 10, font, DARK);
      at("(" + sub + ")", cx + 14 + font.widthOfTextAtSize(label, 10) + 5, y, 8, italic, GRAY);
      cx += 175;
    }
    y -= 26;
  } else {
    y -= 8;
  }

  // ── WEITERE ANGABEN ───────────────────────────────────────────────────────
  //
  // Was der Verein ueber die Kernfelder hinaus gefragt hat. Die Beschriftung
  // steht mit in der Antwort: Wird eine Frage spaeter umformuliert, bleibt
  // trotzdem lesbar, worauf jemand geantwortet hat.
  const zusatz = Object.values(app.extra ?? {}).filter((e) => e && e.wert !== null && e.wert !== "");
  if (zusatz.length > 0) {
    at("WEITERE ANGABEN", L, y, 7.5, bold, AMBER);
    y -= 4; hline(y); y -= 14;

    for (const eintrag of zusatz) {
      const wert = Array.isArray(eintrag.wert)
        ? eintrag.wert.join(", ")
        : typeof eintrag.wert === "boolean"
        ? (eintrag.wert ? "ja" : "nein")
        : String(eintrag.wert);
      at(safe(eintrag.label), L, y, 9, bold, GRAY);
      y = textBlock(safe(wert), L + 148, y, 10, font, DARK, W - 148);
      y -= 6;
    }
    y -= 8;
  }

  // ── ERKLARUNG ─────────────────────────────────────────────────────────────
  at(texte.erklaerung.titel, L, y, 7.5, bold, AMBER);
  y -= 4; hline(y); y -= 4;

  page.drawRectangle({ x: L, y: y - 72, width: W, height: 76, color: rgb(0.98, 0.98, 0.98) });
  y -= 10;
  // Die erste Zeile steht fett – sie ist die eigentliche Erklaerung, der Rest
  // sind die Bedingungen dazu.
  texte.erklaerung.zeilen.forEach((zeile, i) => {
    y = textBlock(zeile, L + 8, y, i === 0 ? 9.5 : 9, i === 0 ? bold : font, DARK, W - 16) - 2;
  });
  y -= 16;

  // ── DATENSCHUTZ ───────────────────────────────────────────────────────────
  at(texte.datenschutz.titel, L, y, 7.5, bold, AMBER);
  y -= 4; hline(y); y -= 14;

  y = textBlock(texte.datenschutz.text, L, y, 8.5, font, rgb(0.35, 0.35, 0.38), W);
  y -= 14;

  // ── EINVERSTANDNIS ────────────────────────────────────────────────────────
  //
  // Die Saetze sind jetzt dieselben wie im Webformular und damit laenger als
  // die frueheren Kurzformen („Satzung anerkannt"). Sie werden umbrochen; das
  // Kaestchen bleibt in der ersten Zeile stehen.
  //
  // {{satzung}} ist im Formular ein Verweis – auf Papier bleibt das Wort.
  for (const [zeile, gesetzt] of [
    [texte.zustimmungen[0] ?? "", app.statutes_accepted],
    [texte.zustimmungen[1] ?? "", app.data_processing_accepted],
  ] as [string, boolean][]) {
    checkbox(L, y, gesetzt);
    const danach = textBlock(zeile.replace(/\{\{\s*satzung\s*\}\}/g, "Satzung"),
      L + 14, y, 9.5, font, DARK, W - 14);
    y = danach - 4;
  }
  y -= 22;

  // ── FOOTER ────────────────────────────────────────────────────────────────
  page.drawRectangle({ x: L, y: y + 2, width: W, height: 1, color: AMBER });
  y -= 14;

  const submitted = fmtDate(app.created_at);
  at("Eingangsdatum:", L, y, 8.5, bold, GRAY);
  at(submitted, L + 92, y, 10, bold, DARK);

  page.drawRectangle({ x: L + W / 2, y: y - 12, width: W / 2, height: 28,
    borderColor: AMBER, borderWidth: 0.8, color: rgb(1, 0.98, 0.96) });
  at(texte.fussnote[0] ?? "", L + W / 2 + 8, y + 8, 7.5, italic, GRAY);
  at(texte.fussnote[1] ?? "", L + W / 2 + 8, y - 3, 7.5, italic, GRAY);

  // Amber-Balken unten
  page.drawRectangle({ x: 0, y: 0, width: 595.28, height: 5, color: AMBER });

  return await pdf.save();
}


Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("Nicht authentifiziert");

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const userClient = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY")!, {
      global: { headers: { Authorization: authHeader } },
    });
    const { data: { user } } = await userClient.auth.getUser();
    if (!user) throw new Error("Nicht authentifiziert");

    const adminClient = createClient(supabaseUrl, serviceRoleKey);

    await requirePermission(
      adminClient,
      user.id,
      "members.manage",
      "Keine Berechtigung, Mitglieder einzuladen"
    );

    const { email, role, applicationId } = await req.json();
    if (!email || !role) throw new Error("E-Mail und Rolle erforderlich");
    await requireValidRole(adminClient, role);

    // Optional application context
    let app: Application | null = null;
    if (applicationId) {
      const { data: appData } = await adminClient
        .from("membership_applications")
        .select("*")
        .eq("id", applicationId)
        .single();
      app = appData as Application | null;
    }

    // Check if user already exists by email
    const { data: existingUsers } = await adminClient.auth.admin.listUsers();
    const existingUser = existingUsers?.users?.find((u) => u.email === email);

    let userId: string;
    let isNewUser = false;
    let confirmUrl: string | null = null;

    const origin = await seitenAdresse();

    if (existingUser) {
      userId = existingUser.id;
      await adminClient.from("user_roles").delete().eq("user_id", userId);
      const { error: roleError } = await adminClient.from("user_roles").insert({ user_id: userId, role });
      if (roleError) throw roleError;
    } else {
      isNewUser = true;
      const { data: linkData, error: linkError } = await adminClient.auth.admin.generateLink({
        type: "invite",
        email,
        options: {
          data: { display_name: app ? `${app.first_name} ${app.last_name}` : email.split("@")[0] },
          redirectTo: `${origin}/passwort-zuruecksetzen`,
        },
      });
      if (linkError) throw linkError;
      userId = linkData.user.id;
      const { error: roleError } = await adminClient.from("user_roles").insert({ user_id: userId, role });
      if (roleError) throw roleError;
      const tokenHash = linkData.properties?.hashed_token;
      confirmUrl = `${origin}/passwort-zuruecksetzen?token_hash=${tokenHash}&type=invite`;
    }

    // If we have an application, pre-fill the profile and attach the generated PDF
    if (app) {
      // Profile update
      const today = new Date().toISOString().slice(0, 10);
      await adminClient.from("profiles").update({
        display_name: `${app.first_name} ${app.last_name}`,
        salutation: app.salutation,
        first_name: app.first_name,
        last_name: app.last_name,
        phone: app.phone,
        birthdate: app.birthdate,
        street: app.street,
        zip: app.zip,
        city: app.city,
        membership_type: app.membership_type,
        contribution_interval: app.contribution_interval,
        entry_date: today,
        is_active: true,
        exit_date: null,
      }).eq("id", userId);

      // Generate PDF and store
      try {
        const rate = await getCurrentRate(adminClient);
        const officials = await getOfficials(adminClient);
        const beitrag = await beitragsangaben(adminClient);
        // Der gedruckte Betrag ist der der gewaehlten Mitgliedsart, nicht ein
        // Satz fuer alle.
        const satz = beitrag.arten.find((a) => a.key === app.membership_type)?.amount ?? rate;
        const pdfBytes = await buildApplicationPdf(
          app, satz, officials, await marke(), await antragsTexte(satz, beitrag.modell), beitrag
        );
        const fileName = `Mitgliedsantrag_${app.last_name}_${app.first_name}.pdf`.replace(/[^a-zA-Z0-9._-]/g, "_");
        const storagePath = `membership/${userId}/${Date.now()}_${fileName}`;
        const { error: upErr } = await adminClient.storage
          .from("internal-files")
          .upload(storagePath, pdfBytes, { contentType: "application/pdf", upsert: true });
        if (!upErr) {
          await adminClient.from("membership_files").insert({
            user_id: userId,
            name: fileName,
            storage_path: storagePath,
            uploaded_by: user.id,
          });
        } else {
          console.error("PDF upload failed:", upErr.message);
        }
      } catch (pdfErr) {
        console.error("PDF generation failed:", pdfErr);
      }

      // Mark application as created_user_id
      await adminClient
        .from("membership_applications")
        .update({ created_user_id: userId })
        .eq("id", app.id);
    }

    // Beschriftung der zugewiesenen Rolle aus dem Rollenkatalog. Eine eigene
    // Liste im Code wuerde bei jeder neuen Rolle wieder auseinanderlaufen.
    const { data: catalogRow } = await adminClient
      .from("role_catalog").select("label").eq("key", role).maybeSingle();
    const assignedRoleLabel = (catalogRow as { label?: string } | null)?.label || role;

    if (isNewUser && confirmUrl) {
      try {
        const { betreff, html } = await baueMail(
          "einladung",
          { rolle: assignedRoleLabel },
          { knopfZiel: confirmUrl }
        );
        await sendeMail(email, betreff, html);
      } catch (emailError) {
        console.error("Email sending failed:", emailError);
      }
    }

    // Willkommensmail an das neue Mitglied (BCC an den Vorstand)
    {
      const firstName = app?.first_name?.trim() || email.split("@")[0];
      const officials = await getOfficials(adminClient);
      const signer = officials.find((o) => o.name);
      const signerName = signer?.name || "Der Vorstand";

      const { betreff: willkommenBetreff, html: willkommenHtml } = await baueMail(
        "willkommen",
        { vorname: firstName },
        { unterschrift: { name: signerName, amt: signer?.label } }
      );

      try {
        await sendeMail(email, willkommenBetreff, willkommenHtml, { bcc: await vereinsAdresse() });
      } catch (welcomeErr) {
        console.error("Welcome email sending failed:", welcomeErr);
      }
    }

    return new Response(JSON.stringify({ success: true, userId }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Unbekannter Fehler";
    console.error("invite-member error:", message);
    return new Response(JSON.stringify({ error: message }), {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});
